core/comments.css:
& .wp-block-comments-title { margin-bottom: var(--wp--preset--spacing--30); }
& .wp-block-comment-template { list-style: none; margin: 0; padding: 0; }
& .comment-body { margin: 0; }
& .comment-stack { display: flex; flex-direction: column; gap: var(--wp--preset--spacing--20); }
& .comment-meta { display: flex; align-items: flex-start; gap: var(--wp--preset--spacing--20); line-height: 1.2; }
& .comment-meta .wp-block-avatar { flex: 0 0 auto; margin: 0; }
& .comment-meta .wp-block-avatar img { display: block; border-radius: 50%; }
& .comment-author-info { display: flex; flex: 1 1 auto; flex-direction: column; gap: var(--wp--preset--spacing--10); min-width: 0; }
& .comment-author-info > * { margin: 0; }
& .comment-actions { display: flex; flex-wrap: wrap; align-items: center; gap: var(--wp--preset--spacing--20); margin-bottom: var(--wp--preset--spacing--20) !important; line-height: 1.2; }
& .comment-actions > * { margin: 0; }
& .comment-actions a { text-decoration: none; }
& .comment-actions a:hover { text-decoration: underline; }
& .comment-respond { margin-top: var(--wp--preset--spacing--30); }

core/latest-comments.css:
list-style: none; padding: 0; margin: 0;
& > li { margin: 0; padding: 0; }
& > li + li { margin-block-start: var(--wp--preset--spacing--20); }
& > li > article { display: grid; grid-template-columns: 52px minmax(0, 1fr); align-items: start; column-gap: var(--wp--preset--spacing--30); }
& .wp-block-latest-comments__comment-avatar-wrapper { flex: 0 0 auto; margin: 0; }
& .wp-block-latest-comments__comment-avatar { display: block; width: 52px; height: 52px; border-radius: 50%; }
& .wp-block-latest-comments__comment-content-wrapper { display: flex; flex-direction: column; gap: var(--wp--preset--spacing--10); min-width: 0; }
& .wp-block-latest-comments__comment-meta { display: flex; flex-direction: column; align-items: flex-start; gap: var(--wp--preset--spacing--10); line-height: 1.25; }
& .wp-block-latest-comments__comment-author-row { display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--wp--preset--spacing--10) var(--wp--preset--spacing--20); line-height: 1.2; }
& .wp-block-latest-comments__comment-author,
& .wp-block-latest-comments__comment-link { text-decoration: none; }
& .wp-block-latest-comments__comment-author { font-size: var(--wp--preset--font-size--medium); font-weight: var(--wp--custom--font-weight-button); }
& .wp-block-latest-comments__comment-link,
& .wp-block-latest-comments__comment-date,
& .wp-block-latest-comments__comment-on { font-size: var(--wp--preset--font-size--small); }
& .wp-block-latest-comments__comment-author:hover,
& .wp-block-latest-comments__comment-link:hover { text-decoration: underline; }
& .wp-block-latest-comments__comment-date,
& .wp-block-latest-comments__comment-on { opacity: 0.68; }
& .wp-block-latest-comments__comment-excerpt { font-size: var(--wp--preset--font-size--small); line-height: 1.5; margin: 0; }
& .wp-block-latest-comments__comment-excerpt p { margin-block: 0; }
& .wp-block-latest-comments__comment-excerpt p:last-child { margin-bottom: 0; }

core/latest-posts.css:
list-style: none; padding: 0;
& .wp-block-latest-posts__post-title { font-size: var(--wp--preset--font-size--large); }
& .wp-block-latest-posts__post-author { font-size: var(--wp--preset--font-size--small); }
& .wp-block-latest-posts__post-date { font-size: var(--wp--preset--font-size--small); }
& .wp-block-latest-posts__post-excerpt { font-size: var(--wp--preset--font-size--medium); }
& .wp-block-latest-posts__read-more { font-size: var(--wp--preset--font-size--small); }

core/post-comments-form.css:
& { display: grid; gap: var(--wp--preset--spacing--20); }
& form.comment-form { display: grid; gap: var(--wp--preset--spacing--20); }
& .comment-reply-title { margin: 0; }
& .comment-reply-title small { font-size: var(--wp--preset--font-size--small); font-weight: var(--wp--custom--font-weight-body); margin-inline-start: var(--wp--preset--spacing--10); }
& :is(.logged-in-as, .comment-notes, .must-log-in) { margin: 0; font-size: var(--wp--preset--font-size--small); }
& :is(.comment-form-comment, .comment-form-author, .comment-form-email, .comment-form-url, .comment-form-cookies-consent, .form-submit) { margin: 0; }
& form.comment-form > .form-submit { margin-top: var(--wp--preset--spacing--10) !important; }
& :is(.comment-form-author, .comment-form-email, .comment-form-url, .comment-form-comment) > label { display: block; margin-bottom: var(--wp--preset--spacing--10); }
& .comment-form-cookies-consent { display: flex; align-items: flex-start; gap: var(--wp--preset--spacing--10); }
& .comment-form-cookies-consent label { margin: 0; }
& .comment-form-cookies-consent input { margin-top: 0.2em; }

core/quote.css:
position: relative; width: 100%; min-height: 3.75rem; padding-left: calc(var(--wp--preset--spacing--40) + 2.25rem);
&::before { content: "\201C"; position: absolute; left: var(--wp--preset--spacing--20); top: var(--wp--preset--spacing--10); font-family: var(--wp--preset--font-family--display, var(--wp--preset--font-family--heading)); font-size: clamp(3rem, 6vw, 4.25rem); line-height: 0.75; font-weight: var(--wp--custom--font-weight-heading); color: color-mix(in srgb, currentColor 25%, transparent); }
& p { margin-block: 0; }
& cite { display: block; margin-top: var(--wp--preset--spacing--20); }
& cite::before { content: "\2014\00a0"; }

plain.css:
min-height: 4rem; padding-left: calc(var(--wp--preset--spacing--40) + 2.5rem); box-shadow: var(--wp--custom--shadow);
&::before { left: var(--wp--preset--spacing--30); top: var(--wp--preset--spacing--20); color: color-mix(in srgb, currentColor 35%, transparent); }
& cite { opacity: 0.8; }

core/rss.css:
list-style: none; padding: 0; margin: 0;
& .wp-block-rss__item-title { font-size: var(--wp--preset--font-size--large); }
& .wp-block-rss__item-publish-date { font-size: var(--wp--preset--font-size--small); }
& .wp-block-rss__item-excerpt { font-size: var(--wp--preset--font-size--medium); }
